import React, { useState, useEffect } from 'react';
import { api } from './services/api';
import Navigation from './components/Navigation';
import HomePage from './pages/HomePage';
import BeersPage from './pages/BeersPage';
import FriendsPage from './pages/FriendsPage';
import AddBeerPage from './pages/AddBeerPage';
import ProfilePage from './pages/ProfilePage';
import LoginPage from './pages/LoginPage';
import RegisterPage from './pages/RegisterPage';
import BeerDetailPage from './pages/BeerDetailPage';
import UserProfilePage from './pages/UserProfilePage';
import AdminDashboard from './pages/AdminDashboard'; // NEW: Admin dashboard import

function App() {
  const [currentPage, setCurrentPage] = useState('home');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState(null);
  const [beers, setBeers] = useState([]);
  const [selectedBeer, setSelectedBeer] = useState(null);
  const [selectedUser, setSelectedUser] = useState(null);
  const [beerReviews, setBeerReviews] = useState([]);

  // Check if user is logged in on app load
  useEffect(() => {
    const token = localStorage.getItem('authToken');
    const userData = localStorage.getItem('user');

    if (token && userData) {
      try {
        const parsedUser = JSON.parse(userData);
        setUser(parsedUser);
        setIsLoggedIn(true);
      } catch (error) {
        console.error('Error parsing user data:', error);
        localStorage.removeItem('authToken');
        localStorage.removeItem('user');
      }
    }
  }, []);

  // Load beers on app start
  useEffect(() => {
    loadBeers();
  }, []);

  const loadBeers = async () => {
    try {
      const beersData = await api.beers.getAll();
      setBeers(beersData || []);
    } catch (error) {
      console.error('Error loading beers:', error);
    }
  };

  const loadBeerReviews = async (beerId) => {
    try {
      const reviews = await api.reviews.getByBeerId(beerId);
      setBeerReviews(reviews || []);
    } catch (error) {
      console.error('Error loading beer reviews:', error);
      setBeerReviews([]);
    }
  };

  const handleNavigation = (page) => {
    setCurrentPage(page);
  };

  const handleLogin = async (credentials) => {
    try {
      const response = await api.auth.login(credentials);
      setUser(response.user);
      setIsLoggedIn(true);
      setCurrentPage('home');
    } catch (error) {
      throw error;
    }
  };

  const handleRegister = async (userData) => {
    try {
      const response = await api.auth.register(userData);
      setUser(response.user);
      setIsLoggedIn(true);
      setCurrentPage('home');
    } catch (error) {
      throw error;
    }
  };

  const handleLogout = () => {
    api.auth.logout();
    setUser(null);
    setIsLoggedIn(false);
    setCurrentPage('home');
  };

  const handleBeerSelect = (beer) => {
    setSelectedBeer(beer);
    loadBeerReviews(beer._id);
    setCurrentPage('beer-detail');
  };

  const handleUserSelect = (user) => {
    setSelectedUser(user);
    setCurrentPage('user-profile');
  };

  const renderPage = () => {
    switch (currentPage) {
      case 'home':
        return (
          <HomePage 
            beers={beers}
            handleBeerSelect={handleBeerSelect}
            isLoggedIn={isLoggedIn}
          />
        );
      case 'beers':
        return (
          <BeersPage 
            beers={beers}
            handleBeerSelect={handleBeerSelect}
            isLoggedIn={isLoggedIn}
          />
        );
      case 'friends':
        return (
          <FriendsPage 
            isLoggedIn={isLoggedIn}
            handleNavigation={handleNavigation}
            handleUserSelect={handleUserSelect}
          />
        );
      case 'add-beer':
        return (
          <AddBeerPage 
            isLoggedIn={isLoggedIn}
            handleNavigation={handleNavigation}
            handleLogout={handleLogout}
            refreshBeers={loadBeers}
          />
        );
      case 'profile':
        return (
          <ProfilePage 
            isLoggedIn={isLoggedIn}
            user={user}
            handleNavigation={handleNavigation}
            handleBeerSelect={handleBeerSelect}
          />
        );
      case 'login':
        return (
          <LoginPage 
            handleLogin={handleLogin}
            handleNavigation={handleNavigation}
          />
        );
      case 'register':
        return (
          <RegisterPage 
            handleRegister={handleRegister}
            handleNavigation={handleNavigation}
          />
        );
      case 'beer-detail':
        return (
          <BeerDetailPage 
            selectedBeer={selectedBeer}
            beerReviews={beerReviews}
            isLoggedIn={isLoggedIn}
            user={user}
            handleNavigation={handleNavigation}
            handleLogout={handleLogout}
            loadBeerReviews={loadBeerReviews}
            refreshBeers={loadBeers}
          />
        );
      case 'user-profile':
        return (
          <UserProfilePage 
            selectedUser={selectedUser}
          />
        );
      case 'admin':  // NEW: Admin dashboard case
        return (
          <AdminDashboard 
            user={user}
            isLoggedIn={isLoggedIn}
            handleNavigation={handleNavigation}
          />
        );
      default:
        return (
          <HomePage 
            beers={beers} 
            handleBeerSelect={handleBeerSelect} 
            isLoggedIn={isLoggedIn}
          />
        );
    }
  };

  return (
    <div className="App">
      <Navigation 
        currentPage={currentPage}
        handleNavigation={handleNavigation}
        isLoggedIn={isLoggedIn}
        user={user}
        handleLogout={handleLogout}
      />
      {renderPage()}
    </div>
  );
}

export default App;
